30 | /**
31 |  * アプリケーション全体のロギング設定を管理するユーティリティクラス。
32 |  *
33 |  * <p>デフォルト（通常モード）では INFO 以上のメッセージを System.out へ出力する。
34 |  * {@link #enableDebug(Path)} を呼び出すと DEBUG 以上のメッセージを指定ファイルへも書き出す。
35 |  * ファイルのパスは {@link #getLogFile()} で取得できる。</p>
36 |  */
37 | public final class AppLogger {
38 | 
39 |     /** コンソールアペンダーのパターン（メッセージのみ）。 */
40 |     private static final String CONSOLE_PATTERN = "%msg%n";
41 | 
42 |     /** ファイルアペンダーのパターン（タイムスタンプ+レベル+メッセージ）。 */
43 |     private static final String FILE_PATTERN = "%date{yyyy-MM-dd HH:mm:ss.SSS} %-5level %msg%n";
44 | 
45 |     private static Path logFile = null;
46 | 
47 |     private AppLogger() {}
48 | 
49 |     /**
50 |      * 指定クラス用の SLF4J ロガーを返す。
51 |      *
52 |      * @param clazz ロガーを取得するクラス
53 |      * @return {@link org.slf4j.Logger}
54 |      */
55 |     public static org.slf4j.Logger get(Class<?> clazz) {
56 |         return LoggerFactory.getLogger(clazz);
57 |     }
58 | 
59 |     /**
60 |      * アプリケーション起動時にコンソールアペンダーを初期化する。
61 |      * INFO 以上のログを System.out へ出力する。
62 |      * picocli がインスタンス化した後、{@code call()} の前に呼び出す。
63 |      */
64 |     public static void init() {
65 |         LoggerContext ctx = (LoggerContext) LoggerFactory.getILoggerFactory();
66 |         ctx.reset();
67 | 
68 |         // コンソールアペンダー（INFO 以上 → System.out）
69 |         ConsoleAppender<ILoggingEvent> console = new ConsoleAppender<>();
70 |         console.setContext(ctx);
71 |         console.setTarget("System.out");
72 |         PatternLayoutEncoder consoleEncoder = new PatternLayoutEncoder();
73 |         consoleEncoder.setContext(ctx);
74 |         consoleEncoder.setPattern(CONSOLE_PATTERN);
75 |         consoleEncoder.start();
76 |         console.setEncoder(consoleEncoder);
77 |         console.start();
78 | 
79 |         Logger root = ctx.getLogger(Logger.ROOT_LOGGER_NAME);
80 |         root.setLevel(Level.INFO);
81 |         root.addAppender(console);
82 |     }
83 | 
84 |     /**
85 |      * デバッグモードを有効化する。
86 |      * DEBUG 以上のメッセージを指定ファイルへ出力するアペンダーを追加する。
87 |      * コンソール出力は引き続き INFO 以上のみ。
88 |      *
89 |      * @param file デバッグログの出力先ファイルパス
90 |      */
91 |     public static void enableDebug(Path file) {
92 |         logFile = file;
93 | 
94 |         LoggerContext ctx = (LoggerContext) LoggerFactory.getILoggerFactory();
95 | 
96 |         // ファイルアペンダー（DEBUG 以上）
97 |         FileAppender<ILoggingEvent> fileAppender = new FileAppender<>();
98 |         fileAppender.setContext(ctx);
99 |         fileAppender.setFile(file.toAbsolutePath().toString());
100 |         fileAppender.setAppend(false);
101 | 
102 |         PatternLayoutEncoder fileEncoder = new PatternLayoutEncoder();
103 |         fileEncoder.setContext(ctx);
104 |         fileEncoder.setPattern(FILE_PATTERN);
105 |         fileEncoder.start();
106 |         fileAppender.setEncoder(fileEncoder);
107 |         fileAppender.start();
108 | 
109 |         Logger root = ctx.getLogger(Logger.ROOT_LOGGER_NAME);
110 |         root.setLevel(Level.DEBUG);
111 |         root.addAppender(fileAppender);
112 |     }
113 | 
114 |     /**
115 |      * デバッグログファイルのパスを返す。デバッグモードが有効でない場合は {@code null}。
116 |      *
117 |      * @return ログファイルパス、または {@code null}
118 |      */
119 |     public static Path getLogFile() {
