171 |                 if (convertToUtf8 && (sourceEncoding == null || sourceEncoding.isBlank())) {
172 |                     log.debug("対話的入力モード開始");
173 |                     try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
