300 |     // artifactIdとして許可する文字（半角英数字、ハイフン、アンダースコア）以外にマッチする正規表現
301 |     private static final Pattern INVALID_CHARS = Pattern.compile("[^a-z0-9\\-_]");
302 | 
303 |     // キャメルケースの境界（大文字の前）にマッチする正規表現
304 |     private static final Pattern CAMEL_CASE_BOUNDARY = Pattern.compile("(?<=[a-z0-9])(?=[A-Z])");
305 | 
306 |     /**
307 |      * プロジェクト名からMavenのartifactIdとして利用可能な文字列を生成します。
308 |      *
309 |      * @param projectName プロジェクト名
310 |      * @return artifactId用文字列
311 |      */
312 |     public static String convertToArtifactId(String projectName) {
313 |         if (projectName == null || projectName.isBlank()) {
314 |             return "default-artifact";
315 |         }
316 | 
317 |         // 1. パッケージ名が含まれている場合（完全限定名）、最後のクラス名部分だけを抽出
318 |         String simpleName = projectName.substring(projectName.lastIndexOf('.') + 1);
319 | 
320 |         // 2. キャメルケース（OrderManager -> Order-Manager）をハイフン区切りに変換
321 |         String kebabCase = CAMEL_CASE_BOUNDARY.matcher(simpleName).replaceAll("-");
322 | 
323 |         // 3. すべて小文字に変換
324 |         String lowerCase = kebabCase.toLowerCase();
325 | 
326 |         // 4. artifactIdとして使えない文字（日本語や特殊記号など）を完全に除去
327 |         String sanitized = INVALID_CHARS.matcher(lowerCase).replaceAll("");
