184 |     /**
185 |      * Maven Central APIのJSONレスポンスをパースしてMavenDependencyを返す。
186 |      *
187 |      * <p>Maven Central で見つかった場合のスコープは {@code scope} をそのまま使う。
188 |      * 見つからなかった場合（system スコープ）は {@code exported} を MavenDependency にコピーする。</p>
189 |      */
190 |     private static MavenDependency parseResponse(String json, String baseName,
191 |                                                  String absolutePath, String scope, boolean exported) {
192 |         // numFound:0 なら見つからなかった
193 |         Matcher numFoundMatcher = NUM_FOUND_PATTERN.matcher(json);
194 |         if (numFoundMatcher.find()) {
195 |             int numFound = Integer.parseInt(numFoundMatcher.group(1));
196 |             if (numFound == 0) {
197 |                 log.info("  → not found in Maven Central (system scope): {}", baseName);
198 |                 return new MavenDependency(baseName, baseName, "0.0.0", "system", absolutePath, exported);
199 |             }
200 |         }
201 | 
202 |         Matcher gMatcher = GROUP_ID_PATTERN.matcher(json);
203 |         Matcher aMatcher = ARTIFACT_ID_PATTERN.matcher(json);
204 |         Matcher vMatcher = VERSION_PATTERN.matcher(json);
205 | 
206 |         if (gMatcher.find() && aMatcher.find() && vMatcher.find()) {
207 |             String groupId    = gMatcher.group(1);
208 |             String artifactId = aMatcher.group(1);
209 |             String version    = vMatcher.group(1);
210 |             log.info("  → found: {}:{}:{}", groupId, artifactId, version);
211 |             return new MavenDependency(groupId, artifactId, version, scope, null);
212 |         }
213 | 
214 |         // パースに失敗した場合もsystemスコープ
215 |         log.warn("  [WARN] Maven Central APIレスポンスのパースに失敗しました: {}", baseName);
216 |         log.info("  → parse error (system scope): {}", baseName);
217 |         return new MavenDependency(baseName, baseName, "0.0.0", "system", absolutePath, exported);
218 |     }
