115 |         }
116 | 
117 |         try {
118 |             // 2. Eclipseプロジェクト情報をパース
119 |             log.info("");
120 |             log.info("[1/5] Eclipseプロジェクトを解析中...");
121 |             EclipseProject eclipseProject = EclipseProjectParser.parse(eclipsePath);
122 |             log.info("  プロジェクト名: {}", eclipseProject.projectName());
123 |             log.info("  種別: {}", eclipseProject.webProject() ? "Webプロジェクト (WTP)" : "Javaプロジェクト");
124 |             log.info("  Javaソースバージョン: {}", eclipseProject.javaSourceVersion());
125 |             log.info("  Javaターゲットバージョン: {}", eclipseProject.javaTargetVersion());
126 |             if (eclipseProject.webProject()) {
127 |                 log.info("  Web仕様バージョン: {}", eclipseProject.webVersion());
128 |             }
129 |             log.info("  ソースフォルダ: {}", eclipseProject.sourceFolders());
130 |             if (eclipseProject.webProject()) {
