132 |             }
133 |             log.info("  JARファイル数: {}", eclipseProject.jarFiles().size());
134 | 
135 |             if (eclipseProject.javaSourceVersion().isUnknown()) {
136 |                 log.error("Javaソースバージョンを認識できませんでした: {}", eclipseProject.javaSourceVersion());
137 |                 return 1;
138 |             }
139 | 
140 |             log.info("");
141 |             log.info("[2/5] 移行先のMavenプロジェクトを決定中...");
142 |             String defaultArtifactId = convertToArtifactId(eclipseProject.projectName());
143 |             if (groupId == null || groupId.isBlank()) {
144 |                 // オプション未指定の場合は対話的に入力を受け付ける
145 |                 try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
146 |                     log.debug("対話的入力モード開始");
147 |                     groupId = promptIfAbsent(reader, "groupId", groupId, null);
148 |                     artifactId = promptIfAbsent(reader, "artifactId", artifactId, defaultArtifactId);
149 |                     artifactVersion = promptIfAbsent(reader, "artifactVersion", artifactVersion, DEFAULT_ARTIFACT_VERSION);
150 |                     log.debug("groupId: {}", groupId);
151 |                     log.debug("artifactId: {}", artifactId);
152 |                     log.debug("version: {}", artifactVersion);
153 |                     // --convertToUtf8 指定時は sourceEncoding も対話入力
154 |                     if (convertToUtf8) {
155 |                         sourceEncoding = promptIfAbsent(reader, "sourceEncoding", sourceEncoding, null);
156 |                     }
157 |                     log.debug("sourceEncoding: {}", sourceEncoding);
158 |                 }
159 |             } else {
160 |                 // 少なくとも--groupIdが指定されていれば，あとは空ならデフォルトを使用する
161 |                 if (artifactId == null || artifactId.isBlank()) {
162 |                     artifactId = defaultArtifactId;
163 |                 }
164 |                 if (artifactVersion == null || artifactId.isBlank()) {
165 |                     artifactVersion = DEFAULT_ARTIFACT_VERSION;
166 |                 }
167 |                 log.info("groupId: {}", groupId);
168 |                 log.info("artifactId: {}", artifactId);
169 |                 log.info("version: {}", artifactVersion);
170 |                 // --convertToUtf8 指定時は sourceEncoding も対話入力（--groupId 指定時で未指定の場合）
171 |                 if (convertToUtf8 && (sourceEncoding == null || sourceEncoding.isBlank())) {
172 |                     log.debug("対話的入力モード開始");
173 |                     try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
174 |                         sourceEncoding = promptIfAbsent(reader, "sourceEncoding", sourceEncoding, null);
175 |                     }
176 |                     log.debug("sourceEncoding: {}", sourceEncoding);
177 |                 }
178 |             }
