180 |             // --convertToUtf8 指定時の sourceEncoding バリデーション
181 |             Charset srcCharset = null;
182 |             if (convertToUtf8) {
183 |                 try {
184 |                     srcCharset = Charset.forName(sourceEncoding);
185 |                 } catch (Exception e) {
186 |                     log.error("--sourceEncoding が無効な文字セット名です: {}", sourceEncoding);
187 |                     return 1;
188 |                 }
