198 |             log.info("");
199 |             log.info("=== e2m: Eclipse → Maven 変換開始 ===");
200 |             log.info("  入力: {}", eclipsePath.toAbsolutePath());
201 |             log.info("  出力: {}", mavenPath.toAbsolutePath());
202 | 
203 |             // 3.(続き) JAR依存関係を解決
204 |             log.info("");
205 |             log.info("[3/5] JAR依存関係を解決中...");
206 |             List<MavenDependency> dependencies = DependencyResolver.resolve(eclipseProject.jarFiles(), eclipsePath);
207 |             long found = dependencies.stream().filter(d -> !"system".equals(d.scope())).count();
208 |             long system = dependencies.stream().filter(d -> "system".equals(d.scope())).count();
209 |             log.info("  Maven Central で見つかった依存: {} 件", found);
