260 |     /**
261 |      * 引数が null または空の場合にプロンプトを表示して入力を受け付ける。
262 |      * デフォルト値がある場合は "[default]" 形式で表示し、空入力でデフォルト値を採用する。
263 |      *
264 |      * @param reader       入力ストリーム
265 |      * @param name         項目名（表示用）
266 |      * @param value        コマンドライン引数の値（null または空の場合にプロンプト表示）
267 |      * @param defaultValue デフォルト値（null の場合はデフォルトなし）
268 |      * @return 確定した値
269 |      */
270 |     private static String promptIfAbsent(BufferedReader reader, String name,
271 |             String value, String defaultValue) throws Exception {
272 |         if (value != null && !value.isBlank()) {
273 |             return value;
274 |         }
275 |         while (true) {
276 |             if (defaultValue != null) {
277 |                 System.out.print(name + " [" + defaultValue + "]: ");
278 |             } else {
279 |                 System.out.print(name + ": ");
280 |             }
281 |             System.out.flush();
282 |             String line = reader.readLine();
283 |             if (line == null) {
284 |                 // EOF（パイプ等）の場合はデフォルト値を使用
285 |                 return defaultValue != null ? defaultValue : "";
286 |             }
287 |             String trimmed = line.trim();
288 |             if (trimmed.isEmpty()) {
289 |                 if (defaultValue != null) {
290 |                     return defaultValue;
291 |                 }
292 |                 // 対話的入力モードでのメッセージは，ロガーを使わず，直接System.outに出力
293 |                 System.out.print("  値を入力してください。");
294 |                 continue;
295 |             }
296 |             return trimmed;
297 |         }
298 |     }
