137 |     /**
138 |      * ソースフォルダ内のファイルを.javaとリソースに振り分けてコピーする。
139 |      *
140 |      * @param baseDir            コピー元のルート（相対パス計算の基点）
141 |      * @param currentDir         現在処理中のディレクトリ
142 |      * @param javaDestBase       .javaファイルのコピー先ベースディレクトリ
143 |      * @param resourceDest       リソースファイルのコピー先ベースディレクトリ（.properties はここへ）
144 |      * @param resourceDestNormal 通常のリソースコピー先（.properties 以外の非.javaファイルはここへ）
145 |      * @param convertToUtf8      true の場合はエンコーディング変換を行う
146 |      * @param sourceEncoding     変換元エンコーディング
147 |      * @throws IOException ファイルコピーに失敗した場合
148 |      */
149 |     private static void copySourceFolder(Path baseDir, Path currentDir, Path javaDestBase,
150 |                                          Path resourceDest, Path resourceDestNormal,
151 |                                          boolean convertToUtf8, Charset sourceEncoding)
152 |             throws IOException {
153 |         log.debug("  javaDestBase = {}", javaDestBase);
154 |         log.debug("  resourceDest = {}", resourceDest);
155 |         log.debug("  resourceDestNormal = {}", resourceDestNormal);
156 | 
157 |         Files.walk(currentDir)
158 |             .filter(Files::isRegularFile)
159 |             .forEach(srcFile -> {
160 |                 try {
161 |                     Path relative = baseDir.relativize(srcFile);
162 |                     String fileName = srcFile.getFileName().toString();
163 |                     boolean isJava = fileName.endsWith(".java");
164 |                     boolean isProperties = fileName.endsWith(".properties");
165 | 
166 |                     if (isJava) {
167 |                         Path destFile = javaDestBase.resolve(relative);
168 |                         Files.createDirectories(destFile.getParent());
169 |                         if (convertToUtf8) {
170 |                             copyWithEncodingConversion(srcFile, destFile, sourceEncoding);
171 |                             log.debug("  [Java:UTF-8変換] {}", relative);
172 |                         } else {
173 |                             Files.copy(srcFile, destFile, StandardCopyOption.REPLACE_EXISTING);
174 |                             log.debug("  [Java:バイナリコピー] {}", relative);
175 |                         }
176 |                     } else if (isProperties && convertToUtf8) {
177 |                         // .properties: Unicode エスケープ展開 + UTF-8 で resourceDest へ
178 |                         Path destFile = resourceDest.resolve(relative);
179 |                         Files.createDirectories(destFile.getParent());
180 |                         copyPropertiesWithConversion(srcFile, destFile, sourceEncoding);
181 |                         log.debug("  [Properties:UTF-8変換] {}", relative);
182 |                     } else {
183 |                         // その他のリソース（バイナリコピー）
184 |                         Path destFile = resourceDestNormal.resolve(relative);
185 |                         Files.createDirectories(destFile.getParent());
186 |                         Files.copy(srcFile, destFile, StandardCopyOption.REPLACE_EXISTING);
187 |                         log.debug("  [Resource:バイナリコピー] {}", relative);
188 |                     }
189 |                 } catch (IOException e) {
190 |                     throw new RuntimeException("ファイルコピーに失敗しました: " + srcFile, e);
191 |                 }
192 |             });
193 |         log.info("  Copied source folder: {} → {}", currentDir, javaDestBase);
194 |     }
195 | 
196 |     /**
197 |      * Webコンテンツディレクトリを再帰的にコピーする。
198 |      * WEB-INF/lib 直下の .jar ファイルはスキップする。
199 |      * WEB-INF/classes ディレクトリ以下のファイルはすべてスキップする。
200 |      * {@code convertToUtf8=true} の場合、.jsp ファイルはエンコーディング変換を行う。
201 |      *
202 |      * @param srcDir         コピー元ディレクトリ
203 |      * @param destDir        コピー先ディレクトリ
204 |      * @param convertToUtf8  true の場合はエンコーディング変換を行う
205 |      * @param sourceEncoding 変換元エンコーディング（.jsp の pageEncoding が不明な場合に使用）
206 |      * @throws IOException ファイルコピーに失敗した場合
207 |      */
208 |     private static void copyWebContents(Path srcDir, Path destDir,
209 |                                         boolean convertToUtf8, Charset sourceEncoding)
210 |             throws IOException {
211 |         Path excludeJarDir = srcDir.resolve("WEB-INF/lib");
212 |         Path excludeClassesDir = srcDir.resolve("WEB-INF/classes");
213 |         Files.walk(srcDir)
214 |                 .filter(srcPath -> (!srcPath.startsWith(excludeJarDir)
215 |                         || !srcPath.getFileName().toString().endsWith(".jar"))
216 |                         && !srcPath.startsWith(excludeClassesDir))
217 |                 .forEach(srcPath -> {
218 |                     try {
219 |                         Path relative = srcDir.relativize(srcPath);
220 |                         Path destPath = destDir.resolve(relative);
221 |                         if (Files.isDirectory(srcPath)) {
222 |                             Files.createDirectories(destPath);
223 |                             log.debug("  [ディレクトリー作成] {}", relative);
224 |                         } else {
225 |                             Files.createDirectories(destPath.getParent());
226 |                             String fileName = srcPath.getFileName().toString();
227 |                             if (convertToUtf8 && fileName.endsWith(".jsp")) {
228 |                                 Charset jspEncoding = extractJspPageEncoding(srcPath, sourceEncoding);
229 |                                 if (jspEncoding != null) {
230 |                                     copyJspWithConversion(srcPath, destPath, jspEncoding);
231 |                                     log.debug("  [JSP:UTF-8変換] {} (encode={})", relative, jspEncoding);
232 |                                 } else {
233 |                                     // pageEncoding が既に UTF-8 → バイナリコピー
234 |                                     Files.copy(srcPath, destPath, StandardCopyOption.REPLACE_EXISTING);
235 |                                     log.debug("  [JSP:バイナリコピー] {}", relative);
236 |                                 }
237 |                             } else {
238 |                                 Files.copy(srcPath, destPath, StandardCopyOption.REPLACE_EXISTING);
239 |                                 log.debug("  [Web:バイナリコピー] {}", relative);
240 |                             }
241 |                         }
242 |                     } catch (IOException e) {
243 |                         throw new RuntimeException("ファイルコピーに失敗しました: " + srcPath, e);
244 |                     }
245 |                 });
246 |     }
247 | 
248 |     /**
249 |      * テキストファイルを指定エンコードで読み込み、UTF-8 で書き出す。
250 |      *
251 |      * @param src  コピー元ファイル
252 |      * @param dest コピー先ファイル
253 |      * @param from 変換元エンコーディング
254 |      * @throws IOException ファイル読み書きに失敗した場合
255 |      */
256 |     static void copyWithEncodingConversion(Path src, Path dest, Charset from) throws IOException {
257 |         String content = Files.readString(src, from);
258 |         Files.writeString(dest, content, StandardCharsets.UTF_8);
259 |     }
260 | 
261 |     /**
262 |      * .properties ファイルを指定エンコードで読み込み、Unicode エスケープを展開して UTF-8 で書き出す。
263 |      *
264 |      * @param src  コピー元ファイル
265 |      * @param dest コピー先ファイル
266 |      * @param from 変換元エンコーディング
267 |      * @throws IOException ファイル読み書きに失敗した場合
268 |      */
269 |     static void copyPropertiesWithConversion(Path src, Path dest, Charset from) throws IOException {
270 |         List<String> lines = Files.readAllLines(src, from);
271 |         List<String> converted = lines.stream()
272 |                 .map(ProjectCopier::unescapeUnicode)
273 |                 .toList();
274 |         Files.write(dest, converted, StandardCharsets.UTF_8);
275 |     }
276 | 
277 |     /**
278 |      * 文字列中の Unicode エスケープシーケンス（&#92;uXXXX 形式）を Unicode 文字に展開する。
279 |      *
280 |      * @param line 入力文字列
281 |      * @return Unicode エスケープを展開した文字列
282 |      */
283 |     static String unescapeUnicode(String line) {
284 |         Matcher m = UNICODE_ESCAPE_PATTERN.matcher(line);
285 |         if (!m.find()) {
286 |             return line;
287 |         }
288 |         m.reset();
289 |         StringBuilder sb = new StringBuilder();
290 |         while (m.find()) {
291 |             int codePoint = Integer.parseInt(m.group(1), 16);
292 |             m.appendReplacement(sb, Matcher.quoteReplacement(String.valueOf((char) codePoint)));
293 |         }
294 |         m.appendTail(sb);
295 |         return sb.toString();
296 |     }
