298 |     /**
299 |      * JSP ファイルの先頭 4KB を ISO-8859-1 で読み込み、{@code pageEncoding} 属性を検出する。
300 |      *
301 |      * <ul>
302 |      *   <li>検出でき、かつ UTF-8 系でない場合: そのエンコーディングの {@link Charset} を返す</li>
303 |      *   <li>検出できない場合: {@code fallback} を返す</li>
304 |      *   <li>検出でき、かつ既に UTF-8 系の場合: {@code null} を返す（呼び出し元でバイナリコピーに切り替える）</li>
305 |      * </ul>
306 |      *
307 |      * @param jspFile  JSP ファイルのパス
308 |      * @param fallback pageEncoding が見つからない場合に返すエンコーディング
309 |      * @return 変換元エンコーディング、または null（既に UTF-8 の場合）
310 |      * @throws IOException ファイル読み込みに失敗した場合
311 |      */
312 |     static Charset extractJspPageEncoding(Path jspFile, Charset fallback) throws IOException {
313 |         // 先頭 4KB を ISO-8859-1 で読み込む（バイト値をそのまま文字として扱うため）
314 |         byte[] bytes = Files.readAllBytes(jspFile);
315 |         int len = Math.min(bytes.length, JSP_PREAMBLE_BYTES);
316 |         String preamble = new String(bytes, 0, len, StandardCharsets.ISO_8859_1);
317 | 
318 |         Matcher m = JSP_PAGE_ENCODING_PATTERN.matcher(preamble);
319 |         if (!m.find()) {
320 |             return fallback;
321 |         }
322 |         String encodingName = m.group(1).trim();
323 |         // 既に UTF-8 系であれば null を返す
324 |         if (encodingName.equalsIgnoreCase("UTF-8") || encodingName.equalsIgnoreCase("UTF8")) {
325 |             return null;
326 |         }
327 |         try {
328 |             return Charset.forName(encodingName);
329 |         } catch (Exception e) {
330 |             // 不明なエンコーディング名の場合は fallback を使用
331 |             log.warn("  [WARN] JSP の pageEncoding が不明です: {} → fallback を使用", encodingName);
332 |             return fallback;
333 |         }
334 |     }
335 | 
336 |     /**
337 |      * JSP ファイルを指定エンコードで読み込み、{@code pageEncoding} 属性値を {@code UTF-8} に書き換えて出力する。
338 |      *
339 |      * @param src  コピー元 JSP ファイル
340 |      * @param dest コピー先ファイル
341 |      * @param from 変換元エンコーディング
342 |      * @throws IOException ファイル読み書きに失敗した場合
343 |      */
344 |     static void copyJspWithConversion(Path src, Path dest, Charset from) throws IOException {
345 |         String content = Files.readString(src, from);
346 |         // pageEncoding 属性値を UTF-8 に書き換える（シングルクォートとダブルクォートの両方に対応）
347 |         String converted = content.replaceAll(
348 |                 "(<%@\\s*page\\b[^%]*\\bpageEncoding\\s*=\\s*)([\"'])([^\"']+)\\2",
349 |                 "$1$2UTF-8$2");
350 |         Files.writeString(dest, converted, StandardCharsets.UTF_8);
351 |     }
352 | 
353 |     /**
354 |      * ソースフォルダのパス文字列をinputDir基点の絶対Pathに解決する。
355 |      * 先頭の '/' は除去して相対パスとして扱う。
356 |      */
357 |     private static Path resolveSourcePath(Path inputDir, String folderPath) {
358 |         String normalized = folderPath.startsWith("/") ? folderPath.substring(1) : folderPath;
359 |         if (normalized.isEmpty()) {
360 |             return inputDir;
361 |         }
362 |         return inputDir.resolve(normalized);
363 |     }
364 | 
365 |     /**
366 |      * ソースフォルダ名に "test" が含まれるかどうかを判定する。
367 |      * パスの各セグメントを小文字で比較する。
368 |      */
369 |     static boolean isTestFolder(String folderPath) {
370 |         String lower = folderPath.toLowerCase();
371 |         for (String segment : lower.split("[/\\\\]")) {
372 |             if (segment.equals("test") || segment.startsWith("test-") || segment.endsWith("-test")) {
373 |                 return true;
374 |             }
375 |         }
376 |         return false;
377 |     }
378 | }
