34 | /**
35 |  * EclipseProject情報と依存関係リストからMavenのpom.xmlを生成するクラス。
36 |  */
37 | public class PomGenerator {
38 | 
39 |     private static final Logger log = AppLogger.get(PomGenerator.class);
40 | 
41 |     private static final String MAVEN_COMPILER_PLUGIN_VERSION = "3.15.0";
42 |     private static final String MAVEN_WAR_PLUGIN_VERSION = "3.5.1";
43 |     private static final String NATIVE2ASCII_PLUGIN_VERSION = "2.1.1";
44 | 
45 |     private PomGenerator() {}
46 | 
47 |     /**
48 |      * pom.xmlを生成して出力ディレクトリに保存する。
49 |      *
50 |      * @param eclipseProject        パース済みEclipseプロジェクト情報
51 |      * @param dependencies          解決済み依存関係リスト
52 |      * @param groupId               生成するpom.xmlのgroupId
53 |      * @param artifactId            生成するpom.xmlのartifactId
54 |      * @param version               生成するpom.xmlのversion
55 |      * @param effectiveTargetVersion maven.compiler.targetに使用するJavaバージョン。
56 |      * @param convertToUtf8      --convert-to-utf8 オプションが指定されているか
57 |      * @param outputDir          出力ディレクトリ
58 |      * @throws Exception XML生成またはファイル書き込みに失敗した場合
59 |      */
60 |     public static void generate(
61 |             EclipseProject eclipseProject,
62 |             List<MavenDependency> dependencies,
63 |             String groupId,
64 |             String artifactId,
65 |             String version,
66 |             JavaVersion effectiveTargetVersion,
67 |             boolean convertToUtf8,
68 |             Path outputDir) throws Exception {
69 | 
70 |         log.debug("  generate開始");
71 |         DocumentBuilderFactory dbf = DocumentBuilderFactory.newInstance();
72 |         DocumentBuilder db = dbf.newDocumentBuilder();
73 |         Document doc = db.newDocument();
74 | 
75 |         // <project>
76 |         Element project = doc.createElement("project");
77 |         project.setAttribute("xmlns", "http://maven.apache.org/POM/4.0.0");
78 |         project.setAttribute("xmlns:xsi", "http://www.w3.org/2001/XMLSchema-instance");
79 |         project.setAttribute("xsi:schemaLocation",
80 |                 "http://maven.apache.org/POM/4.0.0 http://maven.apache.org/xsd/maven-4.0.0.xsd");
81 |         doc.appendChild(project);
82 | 
83 |         addTextElement(doc, project, "modelVersion", "4.0.0");
84 |         addTextElement(doc, project, "groupId", groupId);
85 |         addTextElement(doc, project, "artifactId", artifactId);
86 |         addTextElement(doc, project, "version", version);
87 | 
88 |         if (eclipseProject.webProject()) {
89 |             log.debug("  packaging: war");
90 |             addTextElement(doc, project, "packaging", "war");
91 |         }
92 | 
93 |         // <properties>
94 |         JavaVersion javaSourceVersion = eclipseProject.javaSourceVersion();
95 |         JavaVersion javaTargetVersion = effectiveTargetVersion;
96 |         Element properties = doc.createElement("properties");
97 |         addTextElement(doc, properties, "project.build.sourceEncoding", "UTF-8");
98 |         addTextElement(doc, properties, "maven.compiler.source", javaSourceVersion.toString());
99 |         addTextElement(doc, properties, "maven.compiler.target", javaTargetVersion.toString());
100 |         project.appendChild(properties);
101 | 
102 |         // <dependencies>
103 |         boolean hasDependencies = !dependencies.isEmpty() || eclipseProject.webProject();
104 |         // libs/compile に JAR があるか（system スコープかつ exported=true）を判定
105 |         boolean hasCompileLibs = dependencies.stream()
106 |                 .anyMatch(d -> "system".equals(d.scope()) && d.exported());
