38 | /**
39 |  * デバッグ情報を ZIP アーカイブとして出力するクラス。
40 |  *
41 |  * <p>出力内容:</p>
42 |  * <ul>
43 |  *   <li>コマンドライン引数一覧（{@code commandline_args.txt}）</li>
44 |  *   <li>実行環境のシステムプロパティ一覧（{@code system_properties.txt}）</li>
45 |  *   <li>Eclipseプロジェクトの {@code .project}，{@code .classpath}，{@code .factorypath}，
46 |  *       {@code .settings/} 以下の全ファイル</li>
47 |  *   <li>Eclipseプロジェクト内の全ファイル一覧（名前・サイズ・日付。JARの場合はSHA1も）</li>
48 |  *   <li>生成したMavenプロジェクトの {@code pom.xml}</li>
49 |  *   <li>生成したMavenプロジェクトの全ファイル一覧（名前・サイズ・日付）</li>
50 |  * </ul>
51 |  */
52 | public class DebugArchiver {
53 | 
54 |     private static final Logger log = AppLogger.get(DebugArchiver.class);
55 | 
56 |     private static final DateTimeFormatter TIMESTAMP_FMT =
57 |             DateTimeFormatter.ofPattern("yyyyMMdd_HHmmss");
58 |     private static final DateTimeFormatter FILETIME_FMT =
59 |             DateTimeFormatter.ofPattern("yyyy-MM-dd'T'HH:mm:ss");
60 | 
61 |     private DebugArchiver() {}
62 | 
63 |     /**
64 |      * デバッグ ZIP を生成して出力ディレクトリに保存する。
65 |      *
66 |      * @param inputDir  Eclipseプロジェクトのルートディレクトリ
67 |      * @param outputDir outputDir（artifactId を含まないトップレベルのディレクトリ）
68 |      * @param mavenDir  生成したMavenプロジェクトのルートディレクトリ
69 |      * @param args      コマンドライン引数のコピー
70 |      * @throws IOException ZIP生成またはファイル書き込みに失敗した場合
71 |      */
72 |     public static void archive(Path inputDir, Path outputDir, Path mavenDir, String[] args) throws IOException {
73 | 
74 |         String timestamp = LocalDateTime.now().format(TIMESTAMP_FMT);
75 |         Path zipPath = outputDir.resolve("e2m_debug_" + timestamp + ".zip");
76 |         Files.createDirectories(outputDir);
77 | 
78 |         log.info("");
79 |         log.info("[DEBUG] デバッグ情報を出力中: {}", zipPath);
80 | 
81 |         // ログファイルをフラッシュしてからZIPに追加するため、先にZIPを作成してログを最後に追加する
82 |         Path logFile = AppLogger.getLogFile();
83 | 
84 |         try (OutputStream fos = Files.newOutputStream(zipPath);
85 |              ZipOutputStream zos = new ZipOutputStream(fos, StandardCharsets.UTF_8)) {
86 | 
87 |             // ── 0. コマンドライン引数一覧 ─────────────────────────────────────
88 |             addText(zos, "commandline_args.txt", buildArgsText(args));
89 | 
90 |             // ── 0b. システムプロパティ一覧 ────────────────────────────────────
91 |             addText(zos, "system_properties.txt", buildSystemPropertiesText());
92 | 
93 |             // ── 1. Eclipseプロジェクトのメタファイル ──────────────────────────
94 |             addEclipseMetaFiles(zos, inputDir);
95 | 
96 |             // ── 2. Eclipseプロジェクトのファイル一覧（JARはSHA1付き）──────────
97 |             addText(zos, "eclipse_files.json", buildEclipseFileListing(inputDir));
98 | 
99 |             // ── 3. 生成したMavenプロジェクトのpom.xml ────────────────────────
100 |             if (mavenDir != null) {
101 |                 Path pomFile = mavenDir.resolve("pom.xml");
102 |                 if (Files.isRegularFile(pomFile)) {
103 |                     addFile(zos, pomFile, "pom.xml");
104 |                 }
105 | 
106 |                 // ── 4. 生成したMavenプロジェクトのファイル一覧 ──────────────
107 |                 addText(zos, "maven_files.json", buildFileListing(mavenDir));
108 |             }
109 | 
110 |             // ── 5. デバッグログファイル ────────────────────────────────────
111 |             if (logFile != null && Files.isRegularFile(logFile)) {
112 |                 addFile(zos, logFile, "e2m_debug.log");
113 |             }
114 |         }
115 | 
116 |         log.info("[DEBUG] 出力完了: {}", zipPath.toAbsolutePath());
117 | 
118 |         // ZIPに取り込まれたログファイルを削除
119 |         if (logFile != null && Files.isRegularFile(logFile)) {
120 |             Files.delete(logFile);
121 |         }
122 |     }
123 | 
124 |     /**
125 |      * コマンドライン引数の一覧をテキスト形式で構築する。
126 |      * 各引数はインデックス付きで1行ずつ出力される。
127 |      *
128 |      * @param args コマンドライン引数のコピー（null または空配列も許容）
129 |      * @return テキスト表現
130 |      */
131 |     private static String buildArgsText(String[] args) {
132 |         StringBuilder sb = new StringBuilder();
133 |         sb.append("# e2m command-line arguments\n");
134 |         if (args == null || args.length == 0) {
135 |             sb.append("(no arguments)\n");
136 |         } else {
137 |             for (int i = 0; i < args.length; i++) {
138 |                 sb.append("args[").append(i).append("] = ").append(args[i]).append("\n");
139 |             }
140 |         }
141 |         return sb.toString();
142 |     }
143 | 
144 |     /**
145 |      * 実行環境の {@link System#getProperties()} を取得し、キーのアルファベット順に
146 |      * テキスト形式で構築する。
147 |      *
148 |      * @return テキスト表現
149 |      */
150 |     private static String buildSystemPropertiesText() {
151 |         StringBuilder sb = new StringBuilder();
152 |         sb.append("# Java System Properties\n");
153 |         Properties props = System.getProperties();
154 |         new TreeMap<>(props).forEach((k, v) ->
155 |                 sb.append(k).append(" = ").append(v).append("\n"));
156 |         return sb.toString();
157 |     }
158 | 
159 |     // ── プライベートヘルパー ──────────────────────────────────────────────────
160 | 
161 |     /**
162 |      * Eclipseプロジェクトのメタファイル（.project, .classpath, .factorypath,
163 |      * .settings/ 以下全て）を ZIP に追加する。
164 |      */
165 |     private static void addEclipseMetaFiles(ZipOutputStream zos, Path inputDir) throws IOException {
166 |         for (String name : new String[]{".project", ".classpath", ".factorypath"}) {
167 |             Path file = inputDir.resolve(name);
168 |             if (Files.isRegularFile(file)) {
169 |                 addFile(zos, file, "eclipse/" + name);
170 |             }
171 |         }
172 |         Path settingsDir = inputDir.resolve(".settings");
173 |         if (Files.isDirectory(settingsDir)) {
174 |             Files.walk(settingsDir)
175 |                     .filter(Files::isRegularFile)
176 |                     .sorted()
177 |                     .forEach(p -> {
178 |                         try {
179 |                             String relative = inputDir.relativize(p).toString().replace('\\', '/');
180 |                             addFile(zos, p, "eclipse/" + relative);
181 |                         } catch (IOException e) {
182 |                             throw new RuntimeException("ZIPへの追加に失敗しました: " + p, e);
183 |                         }
184 |                     });
185 |         }
186 |     }
187 | 
188 |     /**
189 |      * Eclipseプロジェクトのファイル一覧を JSON 形式で構築する。
190 |      * JARファイルの場合は sha1 フィールドも出力する。
191 |      */
192 |     private static String buildEclipseFileListing(Path root) throws IOException {
193 |         List<String> entries = new ArrayList<>();
194 | 
195 |         if (Files.exists(root)) {
196 |             for (Path p : (Iterable<Path>) Files.walk(root).sorted()::iterator) {
197 |                 BasicFileAttributes attrs = Files.readAttributes(p, BasicFileAttributes.class);
198 |                 boolean isDir = attrs.isDirectory();
199 |                 long size = isDir ? 0L : attrs.size();
200 |                 Instant instant = attrs.lastModifiedTime().toInstant();
201 |                 String modified = LocalDateTime.ofInstant(instant, ZoneId.systemDefault())
202 |                         .format(FILETIME_FMT);
203 |                 String relative = root.relativize(p).toString().replace('\\', '/');
204 |                 if (relative.isEmpty()) {
205 |                     relative = ".";
206 |                 }
207 | 
208 |                 StringBuilder entry = new StringBuilder();
209 |                 entry.append("    {");
210 |                 entry.append("\"type\":\"").append(isDir ? "directory" : "file").append("\"");
211 |                 entry.append(",\"path\":\"").append(jsonEscape(relative)).append("\"");
212 |                 entry.append(",\"size\":").append(size);
213 |                 entry.append(",\"lastModified\":\"").append(modified).append("\"");
214 | 
215 |                 if (!isDir && p.getFileName().toString().endsWith(".jar")) {
216 |                     String sha1;
217 |                     try {
218 |                         sha1 = FileUtils.computeSha1(p);
219 |                     } catch (Exception e) {
220 |                         sha1 = null;
221 |                     }
222 |                     if (sha1 != null) {
223 |                         entry.append(",\"sha1\":\"").append(sha1).append("\"");
224 |                     }
225 |                 }
226 | 
227 |                 entry.append("}");
228 |                 entries.add(entry.toString());
229 |             }
230 |         }
231 | 
232 |         StringBuilder sb = new StringBuilder();
233 |         sb.append("{\n");
234 |         sb.append("  \"root\":\"").append(jsonEscape(root.toAbsolutePath().toString())).append("\",\n");
235 |         sb.append("  \"entries\":[\n");
236 |         for (int i = 0; i < entries.size(); i++) {
237 |             sb.append(entries.get(i));
238 |             if (i < entries.size() - 1) sb.append(",");
239 |             sb.append("\n");
240 |         }
241 |         sb.append("  ]\n");
242 |         sb.append("}\n");
243 |         return sb.toString();
244 |     }
245 | 
246 |     /**
247 |      * 指定ディレクトリ以下の全ファイル・ディレクトリ一覧を JSON 形式で返す。
248 |      */
249 |     private static String buildFileListing(Path root) throws IOException {
250 |         List<String> entries = new ArrayList<>();
251 | 
252 |         if (Files.exists(root)) {
253 |             for (Path p : (Iterable<Path>) Files.walk(root).sorted()::iterator) {
254 |                 BasicFileAttributes attrs = Files.readAttributes(p, BasicFileAttributes.class);
255 |                 boolean isDir = attrs.isDirectory();
256 |                 long size = isDir ? 0L : attrs.size();
257 |                 Instant instant = attrs.lastModifiedTime().toInstant();
258 |                 String modified = LocalDateTime.ofInstant(instant, ZoneId.systemDefault())
259 |                         .format(FILETIME_FMT);
260 |                 String relative = root.relativize(p).toString().replace('\\', '/');
261 |                 if (relative.isEmpty()) {
262 |                     relative = ".";
263 |                 }
264 | 
265 |                 entries.add("    {" +
266 |                         "\"type\":\"" + (isDir ? "directory" : "file") + "\"" +
267 |                         ",\"path\":\"" + jsonEscape(relative) + "\"" +
268 |                         ",\"size\":" + size +
269 |                         ",\"lastModified\":\"" + modified + "\"" +
270 |                         "}");
271 |             }
272 |         }
273 | 
274 |         StringBuilder sb = new StringBuilder();
275 |         sb.append("{\n");
276 |         sb.append("  \"root\":\"").append(jsonEscape(root.toAbsolutePath().toString())).append("\",\n");
277 |         sb.append("  \"entries\":[\n");
278 |         for (int i = 0; i < entries.size(); i++) {
279 |             sb.append(entries.get(i));
280 |             if (i < entries.size() - 1) sb.append(",");
281 |             sb.append("\n");
282 |         }
283 |         sb.append("  ]\n");
284 |         sb.append("}\n");
285 |         return sb.toString();
286 |     }
287 | 
288 |     /**
289 |      * JSON 文字列値として安全にエスケープする。
290 |      * バックスラッシュ・ダブルクォート・制御文字を処理する。
291 |      */
292 |     private static String jsonEscape(String s) {
293 |         StringBuilder sb = new StringBuilder(s.length());
294 |         for (int i = 0; i < s.length(); i++) {
295 |             char c = s.charAt(i);
296 |             switch (c) {
297 |                 case '"'  -> sb.append("\\\"");
298 |                 case '\\' -> sb.append("\\\\");
299 |                 case '\b' -> sb.append("\\b");
300 |                 case '\f' -> sb.append("\\f");
301 |                 case '\n' -> sb.append("\\n");
302 |                 case '\r' -> sb.append("\\r");
303 |                 case '\t' -> sb.append("\\t");
304 |                 default -> {
305 |                     if (c < 0x20) {
306 |                         sb.append(String.format("\\u%04x", (int) c));
307 |                     } else {
308 |                         sb.append(c);
309 |                     }
310 |                 }
311 |             }
312 |         }
313 |         return sb.toString();
314 |     }
315 | 
316 |     /** ファイルを ZIP エントリとして追加する。 */
317 |     private static void addFile(ZipOutputStream zos, Path file, String entryName) throws IOException {
318 |         zos.putNextEntry(new ZipEntry(entryName));
319 |         Files.copy(file, zos);
320 |         zos.closeEntry();
321 |     }
322 | 
323 |     /** 文字列テキストを ZIP エントリとして追加する。 */
324 |     private static void addText(ZipOutputStream zos, String entryName, String text) throws IOException {
325 |         byte[] bytes = text.getBytes(StandardCharsets.UTF_8);
326 |         zos.putNextEntry(new ZipEntry(entryName));
327 |         zos.write(bytes);
328 |         zos.closeEntry();
329 |     }
330 | }
